    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values

    (v_aula_id, 1, $p$Tozer adverte que a ortodoxia sem o Espírito é apenas textualismo, e que o intelecto mais brilhante fica obtuso diante dos mistérios de Deus; em que medida você tem confiado na sua capacidade de entender a Bíblia em vez de pedir ao Espírito que a ilumine no seu coração?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O autor afirma que a verdade divina não é só doutrina correta, mas doutrina correta com a iluminação interior do Espírito; você tem buscado essa iluminação humildemente, ou se contentado em romper apenas a casca exterior das palavras?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Ele ensina, com Atanásio e os antigos, que um coração impuro não pode conhecer a verdade divina, e que é preciso purificar a alma para compreender; que iniquidades você precisa abandonar para que os seus olhos espirituais sejam abertos por Deus?$p$, 'reflexao', null);
